// Replays proto/testdata/steering_vectors.json (generated by
// proto/go/steering/vectors_test.go), then checks over random inputs the
// invariants the vectors can't reach, as proto/go/steering/steering_test.go
// does on the Go side.

import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'

import * as steering from '../src/steering/index.js'
import {
    RELAY_REPUTATION_COOLDOWN_MS,
    RELAY_TIMEOUT_COOLDOWN_MS,
    TARGET_BACKOFF_BASE_MS,
    TARGET_BACKOFF_CAP_MS,
    WEIGHTS_CONSENSUS_MIN_OWNERS,
    backoffRemaining,
    backoffWindowMs,
    bump,
    contradictsWeightsConsensus,
    decay,
    isForwardTimeoutStatus,
    recordFailure,
    relayDownranked,
    weightsConsensus,
    type Backoff,
    type DigestClaim,
    type Evidence,
} from '../src/steering/index.js'
import { isRelayFrontDoorStatus } from '../src/transient/index.js'

type Json = Record<string, any> // eslint-disable-line @typescript-eslint/no-explicit-any

const here = path.dirname(fileURLToPath(import.meta.url))
const v = JSON.parse(
    fs.readFileSync(path.resolve(here, '..', '..', 'testdata', 'steering_vectors.json'), 'utf8'),
) as Json

const evidence = (e: Json | null): Evidence | undefined => (e === null ? undefined : { count: e.count, at: e.at_ms })
const backoff = (b: Json | null): Backoff | undefined =>
    b === null ? undefined : { failures: b.failures, at: b.at_ms, until: b.until_ms }

describe('steering_vectors.json', () => {
    it('is the schema this test expects', () => {
        expect(v.version).toBe(1)
        for (const k of ['forward_timeout_statuses', 'decay', 'backoff_windows', 'backoff', 'weights_consensus', 'relay_downranked']) {
            expect(v[k].length).toBeGreaterThan(0)
        }
    })

    describe('constants', () => {
        for (const [name, want] of Object.entries(v.constants as Record<string, number>)) {
            it(name, () => expect((steering as Record<string, unknown>)[name]).toBe(want))
        }
    })

    it('isForwardTimeoutStatus', () => {
        for (const c of v.forward_timeout_statuses) expect(isForwardTimeoutStatus(c.status), String(c.status)).toBe(c.timeout)
    })

    it('relayDownranked', () => {
        for (const c of v.relay_downranked) {
            expect(relayDownranked(c.failures, c.stale, c.timeouts), JSON.stringify(c)).toBe(c.downranked)
        }
    })

    describe('decay and bump', () => {
        for (const c of v.decay) {
            it(c.name, () => {
                const e = evidence(c.evidence)
                expect(decay(e, c.now_ms, c.cooldown_ms)).toStrictEqual(evidence(c.decayed))
                expect(bump(e, c.now_ms, c.cooldown_ms)).toStrictEqual(evidence(c.bumped))
            })
        }
    })

    it('backoffWindowMs', () => {
        for (const c of v.backoff_windows) expect(backoffWindowMs(c.failures), String(c.failures)).toBe(c.window_ms)
    })

    describe('backoffRemaining and recordFailure', () => {
        for (const c of v.backoff) {
            it(c.name, () => {
                const b = backoff(c.backoff)
                expect(backoffRemaining(b, c.now_ms, c.floor_ms)).toStrictEqual({
                    remainingMs: c.remaining_ms,
                    forget: c.forget,
                })
                expect(recordFailure(b, c.now_ms)).toStrictEqual(backoff(c.failed))
            })
        }
    })

    describe('weightsConsensus', () => {
        for (const c of v.weights_consensus) {
            it(c.name, () => {
                const claims: DigestClaim[] = (c.claims ?? []).map((x: Json) => ({ owner: x.owner, digest: x.digest }))
                const consensus = weightsConsensus(claims)
                expect(consensus).toBe(c.consensus === '' ? undefined : c.consensus)
                expect(claims.map((x) => contradictsWeightsConsensus(x.digest, consensus))).toEqual(c.contradicts)
            })
        }
    })
})

// mulberry32: deterministic, so a failure reproduces.
function rng(seed: number) {
    let a = seed >>> 0
    const next = () => {
        a = (a + 0x6d2b79f5) >>> 0
        let t = a
        t = Math.imul(t ^ (t >>> 15), t | 1)
        t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296
    }
    return { int: (n: number) => Math.floor(next() * n), pick: <T>(xs: readonly T[]) => xs[Math.floor(next() * xs.length)] as T }
}

const TRIALS = 5000
const T0 = 1_760_000_000_000
const HOUR = 3_600_000

describe('steering invariants', () => {
    it('keeps the timeout statuses out of the front-door charge set', () => {
        let timeouts = 0
        for (let s = 0; s < 1000; s++) {
            if (!isForwardTimeoutStatus(s)) continue
            timeouts++
            expect(isRelayFrontDoorStatus(s), String(s)).toBe(false)
        }
        expect(timeouts).toBe(3)
    })

    it('decay never grows, is idempotent, composes, and ignores a backwards clock', () => {
        const r = rng(1)
        for (let i = 0; i < TRIALS; i++) {
            const e: Evidence = { count: r.int(12), at: T0 + r.int(6 * HOUR) - 3 * HOUR }
            const now = T0 + r.int(6 * HOUR) - 3 * HOUR
            const cd = r.pick([RELAY_REPUTATION_COOLDOWN_MS, RELAY_TIMEOUT_COOLDOWN_MS, 1000])
            const got = decay(e, now, cd)

            expect(got === undefined || got.count > 0).toBe(true)
            expect(got?.count ?? 0).toBeLessThanOrEqual(e.count)
            if (now < e.at && e.count > 0) expect(got).toStrictEqual(e)
            if (got !== undefined && now >= e.at) {
                expect(got.at).toBeGreaterThanOrEqual(e.at)
                expect(got.at).toBeLessThanOrEqual(now)
            }
            expect(decay(got, now, cd)).toStrictEqual(got)
            if (now > e.at) {
                const mid = e.at + r.int(now - e.at + 1)
                expect(decay(decay(e, mid, cd), now, cd)).toStrictEqual(got)
                if (e.count > 0) expect(got?.count ?? 0).toBe(Math.max(e.count - Math.trunc((now - e.at) / cd), 0))
            }
            expect(bump(e, now, cd)).toStrictEqual({ count: (got?.count ?? 0) + 1, at: now })
        }
    })

    it('backoff windows stay within base and cap, and remaining never outlasts the window', () => {
        let prev = 0
        for (let n = 1; n <= 200; n++) {
            const w = backoffWindowMs(n)
            expect(w).toBeGreaterThanOrEqual(Math.max(prev, TARGET_BACKOFF_BASE_MS))
            expect(w).toBeLessThanOrEqual(TARGET_BACKOFF_CAP_MS)
            prev = w
        }
        expect(backoffWindowMs(2 ** 30)).toBe(TARGET_BACKOFF_CAP_MS)

        const r = rng(2)
        for (let i = 0; i < TRIALS; i++) {
            const at = T0 + r.int(6 * HOUR) - 3 * HOUR
            let b = recordFailure(undefined, at)
            for (let k = r.int(8); k > 0; k--) b = recordFailure(b, at)
            const floor = r.int(10 * 60_000)
            const now = T0 + r.int(6 * HOUR) - 3 * HOUR
            const { remainingMs, forget } = backoffRemaining(b, now, floor)

            expect(remainingMs).toBeGreaterThanOrEqual(0)
            // A clock behind the last failure holds the demotion; from the
            // failure on, it never outlasts the window.
            if (now >= b.at) expect(remainingMs).toBeLessThanOrEqual(Math.max(b.until - b.at, floor))
            if (remainingMs > 0) expect(forget).toBe(false)
            expect(backoffRemaining(b, now + 1000, floor).remainingMs).toBeLessThanOrEqual(remainingMs)
            expect(backoffRemaining(b, now, 0).remainingMs).toBeLessThanOrEqual(remainingMs)
            const next = recordFailure(b, now)
            expect(next.failures).toBe(b.failures + 1)
            expect(next.until - next.at).toBeGreaterThanOrEqual(b.until - b.at)
        }
    })

    it('consensus ignores claim order and repeated claims, and needs enough owners', () => {
        const r = rng(3)
        const digests = ['sha256:aa', 'sha256:bb', 'sha256:cc', '']
        const owners = ['A', 'B', 'C', 'D', 'E', '']
        for (let i = 0; i < TRIALS; i++) {
            const claims: DigestClaim[] = Array.from({ length: r.int(9) }, () => ({
                owner: r.pick(owners),
                digest: r.pick(digests),
            }))
            const want = weightsConsensus(claims)
            const shuffled = [...claims]
            for (let k = shuffled.length - 1; k > 0; k--) {
                const j = r.int(k + 1)
                ;[shuffled[k], shuffled[j]] = [shuffled[j]!, shuffled[k]!]
            }
            expect(weightsConsensus(shuffled)).toBe(want)
            if (claims.length > 0) expect(weightsConsensus([...claims, r.pick(claims)])).toBe(want)
            if (want === undefined) {
                for (const c of claims) expect(contradictsWeightsConsensus(c.digest, want)).toBe(false)
                continue
            }
            const backers = new Set(claims.filter((c) => c.owner && c.digest === want).map((c) => c.owner))
            expect(backers.size).toBeGreaterThanOrEqual(WEIGHTS_CONSENSUS_MIN_OWNERS)
            expect(contradictsWeightsConsensus(undefined, want)).toBe(false)
            expect(contradictsWeightsConsensus(want.toUpperCase(), want)).toBe(false)
        }
    })
})
